    const htmlFile = path.join(this.config.reportDir, 'comprehensive-test-report.html');
    fs.writeFileSync(htmlFile, htmlContent);
    console.log(`📄 HTML report saved to: ${htmlFile}`);
  }

  generateRecommendations() {
